document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(d?.hotelArea){state.hotelCompare.area=d.hotelArea;persist()}if(d?.hotelSelect){state.hotelCompare.selected=d.hotelSelect;persist();toast('已保存住宿比較選擇')}});renderHotels();
